      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp8(:), tmp10(:), &
                               tmp13(:), tmp14(:), tmp16(:), tmp17(:), tmp18(:), tmp19(:), &
                               tmp20(:), tmp21(:), tmp22(:), tmp23(:), tmp24(:), tmp25(:), &
                               tmp26(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), tmp31(:), &
