   !> Nonlocal PCM (gaussian charges): gradient tangents along blocks of directions
   !>
   !> - Directions of the cavity and QM inputs; for the inputs of the last solve
   !> - Needs nonlocal_pcm_weights on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of nonlocal_pcm
   !> @param[in] dr  direction for r
   !> @param[in] dn  direction for n
   !> @param[in] dk1  direction for k1
   !> @param[in] dk2  direction for k2
   !> @param[in] dxi  direction for xi
   !> @param[in] dF  direction for F
   !> @param[in] da  direction for a
   !> @param[in] dv  direction for v
   !> @param[in] dvn  direction for vn
   !> @param[out] hvp_r  hessian times direction, r block
   !> @param[out] hvp_n  hessian times direction, n block
   !> @param[out] hvp_k1  hessian times direction, k1 block
   !> @param[out] hvp_k2  hessian times direction, k2 block
   !> @param[out] hvp_xi  hessian times direction, xi block
   !> @param[out] hvp_F  hessian times direction, F block
   !> @param[out] hvp_a  hessian times direction, a block
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] hvp_vn  hessian times direction, vn block
   !> @param[out] error  error handling; allocated on failure
   subroutine nonlocal_pcm_tangent(state, dr, dn, dk1, dk2, dxi, dF, da, dv, dvn, hvp_r, hvp_n, &
                                   hvp_k1, hvp_k2, hvp_xi, hvp_F, hvp_a, hvp_v, hvp_vn, error)
      !> State of nonlocal_pcm
      type(nonlocal_pcm_state), intent(inout) :: state
      !> Direction for r
      real(wp), contiguous, intent(in) :: dr(:, :, :)
      !> Direction for n
      real(wp), contiguous, intent(in) :: dn(:, :, :)
      !> Direction for k1
      real(wp), contiguous, intent(in) :: dk1(:, :)
      !> Direction for k2
      real(wp), contiguous, intent(in) :: dk2(:, :)
      !> Direction for xi
      real(wp), contiguous, intent(in) :: dxi(:, :)
      !> Direction for F
      real(wp), contiguous, intent(in) :: dF(:, :)
      !> Direction for a
      real(wp), contiguous, intent(in) :: da(:, :)
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Direction for vn
      real(wp), contiguous, intent(in) :: dvn(:, :)
      !> Hessian times direction, r block
      real(wp), contiguous, intent(out) :: hvp_r(:, :, :)
      !> Hessian times direction, n block
      real(wp), contiguous, intent(out) :: hvp_n(:, :, :)
      !> Hessian times direction, k1 block
      real(wp), contiguous, intent(out) :: hvp_k1(:, :)
      !> Hessian times direction, k2 block
      real(wp), contiguous, intent(out) :: hvp_k2(:, :)
      !> Hessian times direction, xi block
      real(wp), contiguous, intent(out) :: hvp_xi(:, :)
      !> Hessian times direction, F block
      real(wp), contiguous, intent(out) :: hvp_F(:, :)
      !> Hessian times direction, a block
      real(wp), contiguous, intent(out) :: hvp_a(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Hessian times direction, vn block
      real(wp), contiguous, intent(out) :: hvp_vn(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call nonlocal_pcm_mf_tangent(state, dr, dn, dk1, dk2, dxi, dF, da, dv, dvn, hvp_r, hvp_n, &
                                      hvp_k1, hvp_k2, hvp_xi, hvp_F, hvp_a, hvp_v, hvp_vn, error)
         return
      end if
      if (state%ready < 4) then
         call fatal_error(error, "[nonlocal_pcm_tangent] call nonlocal_pcm_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(dxi) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dxi: wrong shape")
         return
      end if
      if (any(shape(dF) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dF: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] dvn: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_k2: wrong shape")
         return
      end if
      if (any(shape(hvp_xi) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_xi: wrong shape")
         return
      end if
      if (any(shape(hvp_F) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_F: wrong shape")
         return
      end if
      if (any(shape(hvp_a) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_a: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_v: wrong shape")
         return
      end if
      if (any(shape(hvp_vn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_tangent] hvp_vn: wrong shape")
         return
      end if
      do blk = 1, nblk
         call nonlocal_pcm_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                       dk2(:, blk), dxi(:, blk), dF(:, blk), da(:, blk), &
                                       dv(:, blk), dvn(:, blk), hvp_r(:, :, blk), &
                                       hvp_n(:, :, blk), hvp_k1(:, blk), hvp_k2(:, blk), &
                                       hvp_xi(:, blk), hvp_F(:, blk), hvp_a(:, blk), &
                                       hvp_v(:, blk), hvp_vn(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine nonlocal_pcm_tangent

