         return
      end if
      if (any(shape(dF) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_tangent] dF: wrong shape")
         return
      end if
      if (any(shape(da) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_tangent] da: wrong shape")
         return
      end if
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(dvn) /= [npt, nblk])) then
         call fatal_error(error, "[nonlocal_pcm_mf_tangent] dvn: wrong shape")
         return
      end if
